const rawItems = [];

const extractRss = (nodeName, defaultSource) => {
  try {
    const items = $(nodeName).all();
    for (const item of items) {
      const j = item.json || {};
      const title = String(j.title || j['rss:title'] || '').trim();
      const link = String(j.link || j.guid || j['rss:link'] || '').trim();
      const desc = String(j.contentSnippet || j.content || j.description || '').replace(/<[^>]*>?/gm, '').trim();
      const pubDate = String(j.pubDate || j.isoDate || new Date().toISOString());

      if (title && link) {
        rawItems.push({
          title,
          url: link,
          snippet: desc.slice(0, 300),
          source: defaultSource,
          pubDate
        });
      }
    }
  } catch (e) {}
};

// 1. Feeds de Venezuela
extractRss('RSS El Nacional', 'El Nacional (Venezuela)');
extractRss('RSS Tal Cual', 'Tal Cual Digital (Venezuela)');
extractRss('RSS La Verdad', 'La Verdad (Venezuela)');
extractRss('RSS Alertas 24', 'Alertas 24 (Venezuela)');
extractRss('RSS Twitter Venezuela', 'X / Twitter (Venezuela)');

// Scraper HTML El Universal
try {
  const elUniItems = $('HTTP El Universal').all();
  for (const item of elUniItems) {
    const html = String(item.json?.data || '');
    const regex = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
    let match;
    let count = 0;
    while ((match = regex.exec(html)) !== null && count < 25) {
      const rawHref = match[1];
      const linkText = match[2].replace(/<[^>]*>?/gm, '').trim();
      if (linkText.length > 25 && !linkText.includes('Publicidad') && !linkText.includes('Términos')) {
        let fullUrl = rawHref;
        if (fullUrl.startsWith('/')) {
          fullUrl = 'https://www.eluniversal.com' + fullUrl;
        }
        if (fullUrl.startsWith('http')) {
          rawItems.push({
            title: linkText,
            url: fullUrl,
            snippet: linkText,
            source: 'El Universal (Venezuela)',
            pubDate: new Date().toISOString()
          });
          count++;
        }
      }
    }
  }
} catch (e) {}

// 2. Feeds Internacionales, Deportes y X/Twitter Global
extractRss('RSS El Pais', 'El País Internacional');
extractRss('RSS BBC Mundo', 'BBC Mundo');
extractRss('RSS NYTimes World', 'NYTimes RSS');
extractRss('RSS Twitter Global', 'X / Twitter (Internacional / USA)');

// 3. APIs Externas (si están configuradas)
try {
  const nytItems = $('API NYTimes TopStories').all();
  for (const item of nytItems) {
    const results = item.json?.results || [];
    for (const r of results) {
      if (r.title && r.url) {
        rawItems.push({
          title: String(r.title).trim(),
          url: String(r.url).trim(),
          snippet: String(r.abstract || '').slice(0, 300),
          source: 'NYTimes API',
          pubDate: String(r.published_date || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

try {
  const gnewsItems = $('API GNews TopHeadlines').all();
  for (const item of gnewsItems) {
    const articles = item.json?.articles || [];
    for (const a of articles) {
      if (a.title && a.url) {
        rawItems.push({
          title: String(a.title).trim(),
          url: String(a.url).trim(),
          snippet: String(a.description || '').slice(0, 300),
          source: 'GNews API',
          pubDate: String(a.publishedAt || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

try {
  const newsApiItems = $('API NewsAPI Technology').all();
  for (const item of newsApiItems) {
    const articles = item.json?.articles || [];
    for (const a of articles) {
      if (a.title && a.url) {
        rawItems.push({
          title: String(a.title).trim(),
          url: String(a.url).trim(),
          snippet: String(a.description || '').slice(0, 300),
          source: 'NewsAPI Tech',
          pubDate: String(a.publishedAt || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

try {
  const wnItems = $('API WorldNews').all();
  for (const item of wnItems) {
    const news = item.json?.news || [];
    for (const n of news) {
      if (n.title && n.url) {
        rawItems.push({
          title: String(n.title).trim(),
          url: String(n.url).trim(),
          snippet: String(n.text || '').slice(0, 300),
          source: 'WorldNews API',
          pubDate: String(n.publish_date || new Date().toISOString())
        });
      }
    }
  }
} catch (e) {}

// Desduplicación por URL y Similitud de Título
const seenUrls = new Set();
const seenTitles = new Set();
const uniqueArticles = [];

const normalizeTitle = (t) => t.toLowerCase().replace(/[^a-z0-9áéíóúñ]/g, '');

for (const art of rawItems) {
  const normUrl = art.url.split('?')[0].toLowerCase();
  const normT = normalizeTitle(art.title);

  if (seenUrls.has(normUrl) || seenTitles.has(normT)) {
    continue;
  }

  seenUrls.add(normUrl);
  seenTitles.add(normT);
  uniqueArticles.push(art);
}

// Balanceo Garantizado: Extraer artículos de Venezuela, USA y resto
const veSources = [
  'El Nacional (Venezuela)',
  'Tal Cual Digital (Venezuela)',
  'La Verdad (Venezuela)',
  'El Universal (Venezuela)',
  'Alertas 24 (Venezuela)',
  'X / Twitter (Venezuela)'
];

const usSources = [
  'NYTimes RSS',
  'NYTimes API',
  'GNews API',
  'NewsAPI Tech',
  'X / Twitter (Internacional / USA)'
];

const veList = [];
const usList = [];
const otherList = [];

for (const art of uniqueArticles) {
  if (veSources.includes(art.source)) {
    veList.push(art);
  } else if (usSources.includes(art.source)) {
    usList.push(art);
  } else {
    otherList.push(art);
  }
}

// Combinar garantizando presencia completa de cada bloque
const balancedArticles = [
  ...veList.slice(0, 35),
  ...usList.slice(0, 25),
  ...otherList.slice(0, 35)
];

let originChatId = null;
try {
  const tgData = $('Telegram Command Trigger').first()?.json || {};
  if (tgData.message && tgData.message.chat) {
    originChatId = String(tgData.message.chat.id);
  }
} catch (e) {}

return [{
  json: {
    total_raw: rawItems.length,
    total_unique: uniqueArticles.length,
    total_ve: veList.length,
    total_us: usList.length,
    origin_chat_id: originChatId,
    articles: balancedArticles
  }
}];

const rawText = $json.choices[0].message.content.trim();
const normData = $('Normalizar y Desduplicar Noticias').first()?.json || {};

const dateStr = new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const header = `📰 *RESUMEN DE NOTICIAS DESTACADAS* 🗞️\n📅 *${dateStr.toUpperCase()}*\n----------------------------------------\n\n`;

const fullText = header + rawText;

function chunkMessage(text, maxLen = 3500) {
  if (text.length <= maxLen) return [text];
  const result = [];
  let rem = text;
  while (rem.length > maxLen) {
    let idx = rem.lastIndexOf('\n\n', maxLen);
    if (idx === -1 || idx < maxLen / 2) {
      idx = rem.lastIndexOf('\n', maxLen);
    }
    if (idx === -1 || idx < maxLen / 2) {
      idx = maxLen;
    }
    result.push(rem.slice(0, idx).trim());
    rem = rem.slice(idx).trim();
  }
  if (rem) result.push(rem);
  return result;
}

const chunks = chunkMessage(fullText, 3500);

return chunks.map((c, i) => ({
  json: {
    part: i + 1,
    total_parts: chunks.length,
    telegram_text: chunks.length > 1 ? `*(Parte ${i + 1}/${chunks.length})*\n\n${c}` : c,
    whatsapp_text: (chunks.length > 1 ? `*(Parte ${i + 1}/${chunks.length})*\n\n${c}` : c).replace(/\*\*/g, '*'),
    origin_chat_id: normData.origin_chat_id || null
  }
}));
